package vn.edu.eaut.lab5.ui;
import vn.edu.eaut.lab5.model.TaiKhoan;import javax.swing.*;import java.awt.*;
public class MainFrame extends JFrame {private final TaiKhoan account;private final JTabbedPane tabs=new JTabbedPane();public MainFrame(TaiKhoan account){this.account=account;setTitle("MiniShop - Quan ly ban hang | "+account.getHoTen()+" ("+account.getVaiTro()+")");setSize(1050,700);setDefaultCloseOperation(EXIT_ON_CLOSE);setLocationRelativeTo(null);build();}public MainFrame(){this(new TaiKhoan("demo","","Nguoi dung demo","ADMIN"));}private void build(){boolean admin="ADMIN".equalsIgnoreCase(account.getVaiTro()),staff="NHANVIEN".equalsIgnoreCase(account.getVaiTro()),accountant="KETOAN".equalsIgnoreCase(account.getVaiTro());if(admin||staff)tabs.addTab("San pham",new SanPhamPanel());if(admin||staff)tabs.addTab("Khach hang",new KhachHangPanel());if(admin||staff||accountant)tabs.addTab("Hoa don",new HoaDonPanel(!accountant));if(admin||accountant)tabs.addTab("Thong ke",new ThongKePanel());if(admin)tabs.addTab("Danh muc",new DanhMucPanel());add(tabs,BorderLayout.CENTER);JPanel status=new JPanel(new BorderLayout());status.add(new JLabel("  Nguoi dung: "+account.getHoTen()+" | Vai tro: "+account.getVaiTro()),BorderLayout.WEST);JButton logout=new JButton("Dang xuat");status.add(logout,BorderLayout.EAST);add(status,BorderLayout.SOUTH);logout.addActionListener(e->{dispose();new LoginFrame().setVisible(true);});}}
